        getOrCreateUnit(school, board, classLevel, 1, unitName);

        // Chapter 1: CBSE 6 - Number Systems and Data Representation
        getOrCreateChapter(school, board, classLevel, unitName, 1, "CBSE 6 - Number Systems and Data Representation");
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 6 - Number Systems and Data Representation", 1, "Which number system uses only two digits (0 and 1) and forms the native language of digital computers?", "MCQ", "Binary Number System (Base 2)", "Decimal System (Base 10)", "Octal System (Base 8)", "Hexadecimal System (Base 16)", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 6 - Number Systems and Data Representation", 1, "The standard human counting system using digits from 0 to 9 is called the _______ number system.", "MCQ", "Decimal (Base 10)", "Binary (Base 2)", "Octal (Base 8)", "Hexadecimal (Base 16)", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 6 - Number Systems and Data Representation", 1, "What is the binary representation of the decimal number 5?", "MCQ", "101", "110", "100", "111", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 6 - Number Systems and Data Representation", 1, "What is the decimal value of the binary number 1010?", "MCQ", "10", "12", "8", "14", "A", null);
