        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 7 - Advanced Excel Functions & Data Visualization", 4, "You have a list of 500 sales records and want to see only sales from the 'North' region. Which tool should you use?", "MCQ", "Filter -> Select 'North'", "Sort Z to A", "Delete all rows", "Change font color", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 7 - Advanced Excel Functions & Data Visualization", 4, "What formula correctly checks if a student score in cell M2 has passed (>=35) with 'Passed' else 'Failed'?", "MCQ", "=IF(M2>=35, \"Passed\", \"Failed\")", "=IF(M2<35, \"Passed\", \"Failed\")", "=CHECK(M2, 35)", "=PASS(M2)", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 7 - Advanced Excel Functions & Data Visualization", 4, "What chart type is best suited to display quarterly company profit comparisons side-by-side?", "MCQ", "Clustered Column Chart", "Scatter Plot", "Pie Chart with 50 slices", "Bubble Chart", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 7 - Advanced Excel Functions & Data Visualization", 4, "Why does copying formula =$A$1*B2 to the next row result in =$A$1*B3?", "MCQ", "$A$1 is absolute and remains fixed, while B2 is relative and adjusts to B3", "Excel made an error", "Both cells are absolute", "Both cells are relative", "A", null);

