        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 7 - Web Fundamentals & HTML5 Structure", 1, "What is the root container tag that encloses all elements of an HTML web document?", "MCQ", "<html> ... </html>", "<head> ... </head>", "<body> ... </body>", "<main> ... </main>", "A", null);
