        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 7 - Web Fundamentals & HTML5 Structure", 1, "Which HTML section holds all the visible content (headings, paragraphs, images) displayed on a web page?", "MCQ", "<body> ... </body>", "<head> ... </head>", "<title> ... </title>", "<meta>", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 7 - Web Fundamentals & HTML5 Structure", 1, "Which HTML heading tag creates the largest, most prominent main heading?", "MCQ", "<h1>", "<h6>", "<head>", "<header>", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 7 - Web Fundamentals & HTML5 Structure", 2, "The tag used to define a regular text paragraph in HTML is <_______>.", "FILL_BLANK", "p", "p, P", "", "", "p", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 7 - Web Fundamentals & HTML5 Structure", 2, "The empty tag used to insert a single line break in HTML without closing tag is <_______>.", "FILL_BLANK", "br", "br, BR", "", "", "br", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 7 - Web Fundamentals & HTML5 Structure", 2, "The empty tag used to draw a horizontal dividing rule across a web page is <_______>.", "FILL_BLANK", "hr", "hr, HR", "", "", "hr", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 7 - Web Fundamentals & HTML5 Structure", 2, "The anchor tag used to create hyperlinks connecting web pages in HTML is <_______>.", "FILL_BLANK", "a", "a, A", "", "", "a", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 7 - Web Fundamentals & HTML5 Structure", 2, "The attribute in the anchor tag <a> that specifies destination webpage URL is _______.", "FILL_BLANK", "href", "href, HREF", "", "", "href", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 7 - Web Fundamentals & HTML5 Structure", 3, "Which tag is used to embed pictures and images into an HTML webpage?", "MCQ", "<img>", "<picture>", "<src>", "<image>", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 7 - Web Fundamentals & HTML5 Structure", 3, "Which attribute in the <img> tag specifies the file path or URL location of the image file?", "MCQ", "src=\"image.jpg\"", "href=\"image.jpg\"", "alt=\"image.jpg\"", "link=\"image.jpg\"", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 7 - Web Fundamentals & HTML5 Structure", 3, "Which attribute in the <img> tag provides alternative descriptive text if the image fails to load?", "MCQ", "alt=\"description\"", "src=\"description\"", "title=\"description\"", "id=\"description\"", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 7 - Web Fundamentals & HTML5 Structure", 3, "Which HTML tag renders enclosed text in bold weight?", "MCQ", "<b> or <strong>", "<i>", "<u>", "<p>", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 7 - Web Fundamentals & HTML5 Structure", 3, "Which HTML heading tag produces the smallest heading size among standard headers?", "MCQ", "<h6>", "<h1>", "<h3>", "<h4>", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 7 - Web Fundamentals & HTML5 Structure", 4, "A student writes: <a href=\"https://cbse.nic.in\">Visit CBSE</a>. What happens when the user clicks this text in a browser?", "MCQ", "The browser navigates directly to the CBSE official website", "The page is deleted", "The browser closes", "A video downloads", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 7 - Web Fundamentals & HTML5 Structure", 4, "Which code snippet correctly displays an image named 'logo.png' with a width of 200 pixels?", "MCQ", "<img src=\"logo.png\" width=\"200\" alt=\"Logo\">", "<image href=\"logo.png\" size=\"200\">", "<pic src=\"logo.png\">", "<img link=\"logo.png\">", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 7 - Web Fundamentals & HTML5 Structure", 4, "What file extension must be used when saving an HTML file in Notepad to open it in a web browser?", "MCQ", ".html or .htm", ".docx", ".xlsx", ".pptx", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 7 - Web Fundamentals & HTML5 Structure", 4, "What is the correct structural hierarchy of an essential HTML5 webpage document?", "MCQ", "<!DOCTYPE html> -> <html> -> <head> & <body> -> </html>", "<body> -> <head> -> <html>", "<html> -> <body> -> <head>", "<title> -> <html> -> <body>", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 7 - Web Fundamentals & HTML5 Structure", 4, "Which HTML element specifies the text displayed in the browser window title tab?", "MCQ", "<title>My School Page</title> placed inside <head>", "<h1>My School Page</h1>", "<meta title=\"My School Page\">", "<p>Title</p>", "A", null);

        // Chapter 3: CBSE 7 - Introduction to Python Programming & Variables
        getOrCreateChapter(school, board, classLevel, unitName, 3, "CBSE 7 - Introduction to Python Programming & Variables");
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 7 - Introduction to Python Programming & Variables", 1, "Who created the Python programming language in 1991 at CWI in the Netherlands?", "MCQ", "Guido van Rossum", "James Gosling", "Dennis Ritchie", "Bjarne Stroustrup", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 7 - Introduction to Python Programming & Variables", 1, "Which built-in Python function is used to output text and variable values to the console screen?", "MCQ", "print()", "echo()", "display()", "write()", "A", null);
