        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 7 - Introduction to Python Programming & Variables", 1, "What character symbol is used to write single-line explanatory comments in Python code?", "MCQ", "# (Hash symbol)", "// (Double Slash)", "/* (Slash Star)", "-- (Double Dash)", "A", null);
