        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 8 - Relational Database Management System (RDBMS) Concepts", 1, "What is an organized collection of related data stored electronically in a structured format?", "MCQ", "Database", "Spreadsheet Macro", "Operating System", "Web Server", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 8 - Relational Database Management System (RDBMS) Concepts", 1, "In a relational database table (RDBMS), what is a single horizontal row representing an entity called?", "MCQ", "Record / Tuple", "Field / Attribute", "Key", "Schema", "A", null);
