        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 8 - Relational Database Management System (RDBMS) Concepts", 2, "A field in one table that links and refers to the Primary Key of another table is a _______ Key.", "FILL_BLANK", "Foreign", "Foreign, Foreign key", "", "", "Foreign", null);
