        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 8 - Relational Database Management System (RDBMS) Concepts", 2, "The number of attributes (columns) in a relation/table is called the _______ of the relation.", "FILL_BLANK", "Degree", "Degree", "", "", "Degree", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 8 - Relational Database Management System (RDBMS) Concepts", 2, "The number of tuples (rows) in a relation/table is called the _______ of the relation.", "FILL_BLANK", "Cardinality", "Cardinality", "", "", "Cardinality", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 8 - Relational Database Management System (RDBMS) Concepts", 3, "Which of the following is a widely used Relational Database Management System (RDBMS)?", "MCQ", "MySQL / PostgreSQL", "MS Word", "Google Chrome", "Adobe Reader", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 8 - Relational Database Management System (RDBMS) Concepts", 3, "What language is the international standard used to query, insert, and manage relational databases?", "MCQ", "SQL (Structured Query Language)", "HTML", "CSS", "Assembly", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 8 - Relational Database Management System (RDBMS) Concepts", 3, "What does NULL represent when stored in a database field?", "MCQ", "Missing, unknown, or unassigned data value", "Zero (0)", "A blank space ' '", "Negative infinity", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 8 - Relational Database Management System (RDBMS) Concepts", 3, "If a table contains 5 columns and 20 rows, what is its Degree and Cardinality?", "MCQ", "Degree = 5, Cardinality = 20", "Degree = 20, Cardinality = 5", "Degree = 100, Cardinality = 1", "Degree = 1, Cardinality = 100", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 8 - Relational Database Management System (RDBMS) Concepts", 3, "Which candidate key is chosen by the database designer as the primary identifier for a table?", "MCQ", "Primary Key", "Alternate Key", "Foreign Key", "Foreign Index", "A", null);
