        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 8 - Relational Database Management System (RDBMS) Concepts", 4, "Why is storing data in an RDBMS superior to maintaining separate paper ledgers or plain text files?", "MCQ", "Reduces data redundancy, ensures data consistency, provides fast search, and secures data", "Uses more paper", "Requires no computers", "Slows down operations", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 8 - Relational Database Management System (RDBMS) Concepts", 4, "In an e-commerce database, an 'Orders' table stores CustomerID to look up customer details in 'Customers' table. What role does CustomerID play in 'Orders'?", "MCQ", "Foreign Key", "Primary Key of Orders", "Redundant Column", "Index Only", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 8 - Relational Database Management System (RDBMS) Concepts", 4, "What constraint prevents entering duplicate values into a table column?", "MCQ", "UNIQUE Constraint / PRIMARY KEY", "NOT NULL only", "DEFAULT constraint", "CHECK constraint only", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 8 - Relational Database Management System (RDBMS) Concepts", 4, "A database designer needs to ensure an 'Age' column never accepts negative numbers. Which constraint accomplishes this?", "MCQ", "CHECK (Age >= 0)", "NOT NULL", "FOREIGN KEY", "PRIMARY KEY", "A", null);

        // Chapter 4: CBSE 8 - Computer Networks and Introduction to Artificial Intelligence
        getOrCreateChapter(school, board, classLevel, unitName, 4, "CBSE 8 - Computer Networks and Introduction to Artificial Intelligence");
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 8 - Computer Networks and Introduction to Artificial Intelligence", 1, "What type of network connects computers within a small localized area like a single room, school, or office?", "MCQ", "LAN (Local Area Network)", "WAN (Wide Area Network)", "MAN (Metropolitan Area Network)", "PAN (Personal Area Network)", "A", null);
