        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 8 - Computer Networks and Introduction to Artificial Intelligence", 2, "The domain of AI that enables computers to interpret, understand, and process human text and speech is _______ (Natural Language Processing).", "FILL_BLANK", "NLP", "NLP, Natural Language Processing", "", "", "NLP", null);
