        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 8 - Computer Networks and Introduction to Artificial Intelligence", 2, "The branch of AI where machines learn and improve from experience and data without explicit programming is _______ Learning.", "FILL_BLANK", "Machine", "Machine, Machine Learning", "", "", "Machine", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 8 - Computer Networks and Introduction to Artificial Intelligence", 3, "What unique numerical 32-bit or 128-bit address identifies every device connected to the internet?", "MCQ", "IP Address (Internet Protocol Address)", "MAC Address", "Port Number", "URL", "A", null);
