        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 8 - Computer Networks and Introduction to Artificial Intelligence", 3, "Which AI application recognizes faces in photos and unlocks modern smartphones securely?", "MCQ", "Computer Vision & Facial Recognition", "Speech Synthesizer", "Spell Checker", "Disk Defragmenter", "A", null);
