        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 9 - Computer Systems Architecture and Memory Hierarchy", 3, "Which bus carries memory address pointers from the CPU to system components?", "MCQ", "Address Bus", "Data Bus", "Control Bus", "Power Bus", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 9 - Computer Systems Architecture and Memory Hierarchy", 3, "Which bus transmits actual data values bidirectionally between CPU, memory, and peripherals?", "MCQ", "Data Bus", "Address Bus", "Control Bus", "Clock Bus", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 9 - Computer Systems Architecture and Memory Hierarchy", 3, "What utility program rearranges fragmented non-contiguous file blocks on a hard disk to speed up read access?", "MCQ", "Disk Defragmenter", "Disk Cleanup", "Backup Utility", "Antivirus", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 9 - Computer Systems Architecture and Memory Hierarchy", 3, "What is permanent low-level firmware burned into hardware ROM chips called?", "MCQ", "Firmware", "Shareware", "Freeware", "Malware", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 9 - Computer Systems Architecture and Memory Hierarchy", 4, "A computer starts lagging severely when 15 heavy apps are opened simultaneously. What bottleneck is occurring?", "MCQ", "Physical RAM is exhausted, causing heavy swapping to slow Virtual Memory on disk (Thrashing)", "Monitor resolution is too high", "Keyboard buffer is full", "Speaker wire is loose", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 9 - Computer Systems Architecture and Memory Hierarchy", 4, "Why is Python classified as an Interpreted programming language?", "MCQ", "Python source code is translated and executed line-by-line at runtime by the Python Virtual Machine (PVM)", "It compiles directly to hardware circuits", "It only runs on supercomputers", "It has no syntax rules", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 9 - Computer Systems Architecture and Memory Hierarchy", 4, "What is the correct hierarchy of memory speed from fastest to slowest?", "MCQ", "Registers > L1/L2 Cache > RAM > SSD / HDD", "HDD > RAM > Cache > Registers", "RAM > Registers > HDD > Cache", "Cache > HDD > RAM > Registers", "A", null);
