        // Chapter 2: CBSE 9 - Cyber Safety, Privacy & Digital Citizenship
        getOrCreateChapter(school, board, classLevel, unitName, 2, "CBSE 9 - Cyber Safety, Privacy & Digital Citizenship");
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 9 - Cyber Safety, Privacy & Digital Citizenship", 1, "What is the total trail of data, posts, search queries, and photos left behind on the internet by an individual?", "MCQ", "Digital Footprint", "Browser Cache", "IP Address", "Cookie", "A", null);
