        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 9 - Cyber Safety, Privacy & Digital Citizenship", 1, "What is a digital footprint created unintentionally through IP logs, cookies, and website tracking called?", "MCQ", "Passive Digital Footprint", "Active Digital Footprint", "Malware Footprint", "Public Profile", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 9 - Cyber Safety, Privacy & Digital Citizenship", 1, "What legal Indian act enacted in 2000 governs cyber law, electronic commerce, and cyber crimes in India?", "MCQ", "Information Technology Act 2000 (IT Act 2000)", "Indian Penal Code 1860", "Companies Act", "Consumer Protection Act", "A", null);
