        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 10 - Database Management System & SQL Queries", 1, "Which category of SQL commands (like CREATE, ALTER, DROP) defines and modifies database structure/schema?", "MCQ", "DDL (Data Definition Language)", "DML (Data Manipulation Language)", "DCL (Data Control Language)", "TCL (Transaction Control Language)", "A", null);
