        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 10 - Database Management System & SQL Queries", 1, "Which SQL command is used to retrieve data records from one or more database tables?", "MCQ", "SELECT", "GET", "RETRIEVE", "FETCH", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 10 - Database Management System & SQL Queries", 1, "Which SQL clause is used to filter records and return only those that meet a specific boolean condition?", "MCQ", "WHERE", "HAVING", "FILTER", "CONDITION", "A", null);
