        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 10 - Database Management System & SQL Queries", 2, "The SQL command used to insert a brand new row of data into a table is _______ INTO.", "FILL_BLANK", "INSERT", "INSERT, insert", "", "", "INSERT", null);
