        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 10 - Database Management System & SQL Queries", 2, "The SQL command used to create a brand new database table with specified columns and datatypes is _______ TABLE.", "FILL_BLANK", "CREATE", "CREATE, create", "", "", "CREATE", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 10 - Database Management System & SQL Queries", 2, "The SQL keyword used to return only unique, non-duplicate values in a SELECT query is _______.", "FILL_BLANK", "DISTINCT", "DISTINCT, distinct", "", "", "DISTINCT", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 10 - Database Management System & SQL Queries", 3, "Which SQL wildcard character represents zero, one, or multiple characters in a LIKE pattern match (e.g. 'A%')?", "MCQ", "% (Percent symbol)", "_ (Underscore)", "* (Asterisk)", "? (Question mark)", "A", null);
