        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 10 - Database Management System & SQL Queries", 3, "Which SQL keyword sorts result records from highest to lowest in an ORDER BY clause?", "MCQ", "DESC (Descending)", "ASC (Ascending)", "TOP", "DOWN", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 10 - Database Management System & SQL Queries", 3, "Which aggregate function in SQL calculates the arithmetic mean of numeric values in a column?", "MCQ", "AVG(column_name)", "MEAN(column_name)", "AVERAGE(column_name)", "SUM(column_name)", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 10 - Database Management System & SQL Queries", 3, "Which SQL clause groups rows having the same values into summary rows (e.g. find total salary per department)?", "MCQ", "GROUP BY", "ORDER BY", "COLLECT BY", "PARTITION", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 10 - Database Management System & SQL Queries", 4, "Write an SQL query to retrieve all columns for students who scored greater than 90 marks from table 'Student'. Which query is correct?", "MCQ", "SELECT * FROM Student WHERE Marks > 90;", "SELECT ALL Student WHERE Marks > 90;", "GET * FROM Student IF Marks > 90;", "FIND Student WHERE Marks > 90;", "A", null);
