        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 10 - Database Management System & SQL Queries", 4, "What query deletes student record with RollNo = 105 from table 'Student'?", "MCQ", "DELETE FROM Student WHERE RollNo = 105;", "REMOVE Student WHERE RollNo = 105;", "DROP Student WHERE RollNo = 105;", "DELETE RollNo = 105 FROM Student;", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 10 - Database Management System & SQL Queries", 4, "What is the output of: SELECT COUNT(*) FROM Student WHERE Marks IS NULL;?", "MCQ", "Returns the total number of students whose marks are not recorded (NULL)", "Returns 0 always", "Causes a syntax error", "Deletes all NULL records", "A", null);
