        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 10 - Python Functions & AI Project Cycle", 1, "What are the 5 structured stages of the official AI Project Cycle in order?", "MCQ", "Problem Scoping -> Data Acquisition -> Data Exploration -> Modelling -> Evaluation", "Coding -> Testing -> Debugging -> Deploying -> Marketing", "Input -> Process -> Output -> Store -> Delete", "Data -> Model -> Code -> Game -> App", "A", null);
