        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 10 - Python Functions & AI Project Cycle", 1, "In the AI Project Cycle, which stage involves collecting relevant, accurate datasets from reliable sources?", "MCQ", "Data Acquisition", "Data Exploration", "Problem Scoping", "Evaluation", "A", null);
