        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 10 - Python Functions & AI Project Cycle", 2, "In Machine Learning, finding hidden patterns and clusters in unlabeled data without target answers is _______ Learning.", "FILL_BLANK", "Unsupervised", "Unsupervised, unsupervised", "", "", "Unsupervised", null);
