        addQuestionIfMissing(school, board, classLevel, unitName, "CBSE 10 - Python Functions & AI Project Cycle", 4, "Write a Python function 'is_even(num)' that returns True if num is even else False. Which implementation is correct?", "MCQ", "def is_even(num): return num % 2 == 0", "def is_even(num): return num / 2", "function is_even(num) { return num % 2 == 0; }", "def is_even: if num % 2 == 0", "A", null);
