        addQuestionIfMissing(school, board, classLevel, unitName, "State Board 6 - Internet and Email Communications", 1, "Which button is clicked in an email client to open a new blank window to write a fresh email?", "MCQ", "Compose / New Message", "Inbox", "Trash", "Spam", "A", null);
