        addQuestionIfMissing(school, board, classLevel, unitName, "State Board 6 - Internet and Email Communications", 2, "Attaching an external photo or PDF document to an email uses the paperclip icon called an _______.", "FILL_BLANK", "Attachment", "Attachment, attachment", "", "", "Attachment", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "State Board 6 - Internet and Email Communications", 2, "Unfinished emails saved automatically by the email system before sending are stored in _______.", "FILL_BLANK", "Drafts", "Drafts, drafts", "", "", "Drafts", null);
