        addQuestionIfMissing(school, board, classLevel, unitName, "State Board 6 - Internet and Email Communications", 3, "In email headers, BCC stands for Blind Carbon Copy. What is its special privacy feature?", "MCQ", "Recipients in BCC cannot see each other's email addresses", "It sends the email in audio format", "It encrypts the subject line", "It deletes the email after reading", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "State Board 6 - Internet and Email Communications", 3, "Which folder stores all copies of successfully delivered outgoing emails?", "MCQ", "Sent / Sent Mail", "Inbox", "Outbox", "Spam", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "State Board 6 - Internet and Email Communications", 3, "Where do deleted emails go before being permanently purged after 30 days?", "MCQ", "Trash / Bin", "Archive", "Starred", "Drafts", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "State Board 6 - Internet and Email Communications", 3, "What should you always include at the end of a formal email to your school teacher?", "MCQ", "A polite sign-off signature with your Full Name, Class, Section, and Roll Number", "A cartoon sticker", "Your password", "No name at all", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "State Board 6 - Internet and Email Communications", 3, "Which popular free email services are widely used worldwide?", "MCQ", "Gmail, Outlook, Yahoo Mail", "Notepad, Paint, Calculator", "VLC, Tux Paint", "Chrome, Firefox", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "State Board 6 - Internet and Email Communications", 4, "A student in Erode wants to email their science project PDF to their teacher. What are the correct steps?", "MCQ", "Open email -> Click Compose -> Type teacher's email in 'To' -> Add Subject -> Click Paperclip icon to attach PDF -> Click Send", "Type on Facebook wall", "Print paper and mail by post", "Send an empty message without attachment", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "State Board 6 - Internet and Email Communications", 4, "You receive an email from an unknown sender with subject 'You won a prize, download gift.exe'. What should you do?", "MCQ", "Do not download or open the attachment; delete the email and report as Spam/Phishing", "Open the executable immediately", "Forward to your friends", "Send your bank details", "A", null);
        addQuestionIfMissing(school, board, classLevel, unitName, "State Board 6 - Internet and Email Communications", 4, "Why is typing an entire email in ALL CAPITAL LETTERS considered bad netiquette (cyber etiquette)?", "MCQ", "Typing in all caps is perceived as SHOUTING and aggressive in digital communications", "It costs more money", "It disables the internet connection", "It deletes the email automatically", "A", null);
